UnityEngine.Application.runInBackground=true;var menu=UnityEngine.Object.FindFirstObjectByType<SettingsMenu>();var gm=GameManager.Instance;var pc=UnityEngine.Object.FindFirstObjectByType<PlayerController>();var pad=UnityEngine.InputSystem.InputSystem.AddDevice<UnityEngine.InputSystem.Gamepad>();int originalId=gm.GetInstanceID();int stage=0;int nextFrame=UnityEngine.Time.frameCount+3;var report=new System.Text.StringBuilder();
UnityEditor.EditorApplication.CallbackFunction watch=null;
watch=()=>{if(!UnityEditor.EditorApplication.isPlaying){UnityEditor.EditorApplication.update-=watch;UnityEngine.InputSystem.InputSystem.RemoveDevice(pad);return;}if(UnityEngine.Time.frameCount<nextFrame)return;
if(stage==0){UnityEngine.InputSystem.InputSystem.QueueStateEvent(pad,new UnityEngine.InputSystem.LowLevel.GamepadState().WithButton(UnityEngine.InputSystem.LowLevel.GamepadButton.Start));stage=1;nextFrame=UnityEngine.Time.frameCount+4;}
else if(stage==1){report.AppendLine("Options opened="+SettingsMenu.IsOpen+" paused="+(UnityEngine.Time.timeScale==0)+" audioPaused="+UnityEngine.AudioListener.pause+" sameScene="+(gm.GetInstanceID()==originalId));UnityEngine.InputSystem.InputSystem.QueueStateEvent(pad,new UnityEngine.InputSystem.LowLevel.GamepadState().WithButton(UnityEngine.InputSystem.LowLevel.GamepadButton.South));stage=2;nextFrame=UnityEngine.Time.frameCount+4;}
else if(stage==2){report.AppendLine("A noDodge="+(!pc.IsDodging)+" noRestart="+(GameManager.Instance.GetInstanceID()==originalId));UnityEngine.InputSystem.InputSystem.QueueStateEvent(pad,new UnityEngine.InputSystem.LowLevel.GamepadState());stage=3;nextFrame=UnityEngine.Time.frameCount+4;}
else if(stage==3){UnityEngine.InputSystem.InputSystem.QueueStateEvent(pad,new UnityEngine.InputSystem.LowLevel.GamepadState().WithButton(UnityEngine.InputSystem.LowLevel.GamepadButton.Start));stage=4;nextFrame=UnityEngine.Time.frameCount+4;}
else if(stage==4){report.AppendLine("Options closed="+(!SettingsMenu.IsOpen)+" resumed="+(UnityEngine.Time.timeScale==1)+" audioResumed="+(!UnityEngine.AudioListener.pause)+" battleNavigationOff="+(!UnityEngine.EventSystems.EventSystem.current.sendNavigationEvents));System.IO.File.WriteAllText("C:/Users/G2320/UnityGame_sotusei/prototype/.uloop/outputs/settings-pad-results.txt",report.ToString());UnityEngine.InputSystem.InputSystem.RemoveDevice(pad);UnityEditor.EditorApplication.update-=watch;UnityEditor.EditorApplication.isPaused=true;}};
